import React, { useEffect, useState } from "react";
import api from "../api/axios";

export default function Orders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("loggedInUser"));

    if (!user) {
      setLoading(false);
      return;
    }

    api.get(`/orders/customer/${user.id}`)
      .then(res => {
        setOrders(Array.isArray(res.data) ? res.data : []);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="container py-5 text-center">
        <div className="spinner-border text-primary" />
        <p className="mt-3 text-muted">Loading your orders...</p>
      </div>
    );
  }

  return (
    <div className="container py-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2 className="fw-bold mb-0">My Orders</h2>
        <span className="text-muted">{orders.length} orders</span>
      </div>

      {orders.length === 0 ? (
        <div className="card text-center p-5 border-0 shadow-sm">
          <h5 className="mb-2">No orders yet</h5>
          <p className="text-muted mb-0">
            Looks like you haven’t placed any orders.
          </p>
        </div>
      ) : (
        orders.map(order => (
          <div key={order.id} className="card mb-4 border-0 shadow-sm">
            {/* Header */}
            <div className="card-header bg-light d-flex justify-content-between align-items-center">
              <div>
                <div className="fw-semibold">Order #{order.id}</div>
                <small className="text-muted">
                  {new Date(order.orderDate).toLocaleDateString()} ·{" "}
                  {new Date(order.orderDate).toLocaleTimeString()}
                </small>
              </div>

              <span
                className={`badge rounded-pill px-3 py-2 ${
                  order.status === "DELIVERED"
                    ? "bg-success"
                    : order.status === "CANCELLED"
                    ? "bg-danger"
                    : "bg-primary"
                }`}
              >
                {order.status}
              </span>
            </div>

            {/* Body */}
            <div className="card-body">
              <div className="d-flex justify-content-between mb-3">
                <span className="text-muted">Total Amount</span>
                <span className="fw-bold fs-5">
                  ₹{order.totalAmount.toFixed(2)}
                </span>
              </div>

              <hr />

              <div className="table-responsive">
                <table className="table align-middle mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>Product</th>
                      <th className="text-center">Qty</th>
                      <th className="text-end">Price</th>
                      <th className="text-end">Subtotal</th>
                    </tr>
                  </thead>
                  <tbody>
                    {order.items?.map(item => (
                      <tr key={item.id}>
                        <td className="fw-medium">
                          {item.product?.name}
                        </td>
                        <td className="text-center">
                          {item.quantity}
                        </td>
                        <td className="text-end">
                          ₹{item.price.toFixed(2)}
                        </td>
                        <td className="text-end fw-semibold">
                          ₹{(item.price * item.quantity).toFixed(2)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
}
